.summary {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 18px 20px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
}

.meeting {
  display: flex;
  align-items: center;
  gap: 20px;
}

.total {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-width: 76px;
  height: 76px;
  border-radius: 14px;
  background: var(--cell-overlap);
  color: var(--cell-overlap-ink);
  box-shadow: 0 6px 18px -6px var(--cell-overlap-glow);
}

.totalValue {
  font-size: 30px;
  font-weight: 700;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.totalUnit {
  margin-top: 3px;
  font-size: 12px;
  font-weight: 600;
  opacity: 0.85;
}

.meetingBody {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
}

.lead {
  margin: 0;
  font-size: 15px;
  font-weight: 550;
}

.muted {
  font-weight: 400;
  color: var(--ink-3);
}

.ranges {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.range {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 30px;
  padding: 0 6px 0 12px;
  border-radius: 999px;
  background: var(--accent-green-soft);
  color: var(--accent-green-ink);
  font-weight: 650;
  font-size: 14px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  cursor: help;
}

.rangeLength {
  padding: 1px 7px;
  border-radius: 999px;
  background: var(--cell-overlap);
  color: var(--cell-overlap-ink);
  font-size: 11px;
  font-weight: 700;
}

.baseList {
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
}

.baseItem {
  display: grid;
  grid-template-columns: minmax(110px, 160px) 44px 1fr;
  align-items: center;
  gap: 12px;
  padding: 9px 0;
  border-top: 1px solid var(--border);
}

.baseItem:first-child {
  border-top: 0;
}

.baseCity {
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.count {
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--accent-green-ink);
}

.inlineWarning {
  grid-column: 2 / -1;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  justify-self: start;
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--warn-soft);
  color: var(--warn-ink);
  font-size: 13px;
  font-weight: 550;
}

.warning {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 14px 16px;
  border: 1px solid var(--warn-border);
  border-radius: var(--radius-md);
  background: var(--warn-soft);
  color: var(--warn-ink);
}

.warning svg {
  flex: none;
  margin-top: 1px;
}

.warning p {
  margin: 0;
  font-size: 14px;
