/* ---------- Shared cell ---------- */

.cell {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  font-variant-numeric: tabular-nums;
  line-height: 1;
  user-select: none;
  transition: background-color 180ms var(--ease), color 180ms var(--ease), box-shadow 120ms var(--ease);
}

.cell[data-status="asleep"] {
  background: repeating-linear-gradient(
    135deg,
    var(--cell-asleep) 0 5px,
    var(--cell-asleep-stripe) 5px 6px
  );
  color: var(--cell-asleep-ink);
}

.cell[data-status="awake"] {
  background: var(--cell-awake);
  color: var(--cell-awake-ink);
}

.cell[data-status="overlap"] {
  background: var(--cell-overlap);
  color: var(--cell-overlap-ink);
  font-weight: 700;
  box-shadow: 0 2px 8px -3px var(--cell-overlap-glow);
}

.cell[data-hovered] {
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--ink) 50%, transparent);
}

.cell[data-status="overlap"][data-hovered] {
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--cell-overlap-ink) 70%, transparent);
}

/* Day boundary marker, drawn in the gap before the first hour of a new local day. */
.cell[data-newday]::before {
  content: "";
  position: absolute;
  background: var(--ink-3);
  border-radius: 2px;
  opacity: 0.7;
}

.cell[data-now]::after {
  content: "";
  position: absolute;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--now);
}

/* ---------- Desktop: cities as rows ---------- */

.desktopScroll {
  overflow-x: auto;
  padding: 2px 2px 6px;
  margin: -2px -2px -6px;
}

.desktop {
  --label-width: 196px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 980px;
}

.desktopRow {
  display: grid;
  grid-template-columns: var(--label-width) repeat(24, minmax(30px, 1fr)) 36px;
  column-gap: 3px;
}

.desktopRow[data-header] {
  height: 26px;
  align-items: end;
}

.desktopRow[data-reference] {
  padding-bottom: 8px;
  margin-bottom: 2px;
  border-bottom: 1px dashed var(--border-strong);
}

.headerLabel {
  align-self: center;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.headerSlot {
  display: flex;
  justify-content: center;
  align-items: flex-end;
  padding-bottom: 4px;
  overflow: visible;
}

.nowPill,
.hoverPill {
  padding: 3px 7px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  line-height: 1;
  white-space: nowrap;
}

.nowPill {
  background: var(--now);
  color: #fff;
}

.hoverPill {
  background: var(--ink);
  color: var(--ink-inverse);
}

.cityInfo {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  min-width: 0;
  padding-right: 12px;
}

.cityNameRow {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

.cityName,
.cityNameButton {
  overflow: hidden;
  text-overflow: ellipsis;
