  padding: 2px 2px 6px;
  margin: -2px -2px -6px;
}

.desktop {
  --label-width: 196px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 980px;
}

.desktopRow {
  display: grid;
  grid-template-columns: var(--label-width) repeat(24, minmax(30px, 1fr)) 36px;
  column-gap: 3px;
}

.desktopRow[data-header] {
  height: 26px;
  align-items: end;
}

.desktopRow[data-reference] {
  padding-bottom: 8px;
  margin-bottom: 2px;
  border-bottom: 1px dashed var(--border-strong);
}

.headerLabel {
  align-self: center;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.headerSlot {
  display: flex;
  justify-content: center;
  align-items: flex-end;
  padding-bottom: 4px;
  overflow: visible;
}

.nowPill,
.hoverPill {
  padding: 3px 7px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  line-height: 1;
  white-space: nowrap;
}

.nowPill {
  background: var(--now);
  color: #fff;
}

.hoverPill {
  background: var(--ink);
  color: var(--ink-inverse);
}

.cityInfo {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  min-width: 0;
  padding-right: 12px;
}

.cityNameRow {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

.cityName,
.cityNameButton {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 15px;
  font-weight: 650;
  letter-spacing: -0.01em;
}

.cityNameButton {
  padding: 0;
  border: 0;
  background: none;
  text-align: left;
  text-decoration: underline;
  text-decoration-color: transparent;
  text-underline-offset: 3px;
  transition: text-decoration-color 140ms var(--ease), color 140ms var(--ease);
}

.cityNameButton:hover {
  text-decoration-color: var(--ink-3);
}

.refBadge {
  flex: none;
  padding: 3px 6px;
  border-radius: 5px;
  background: var(--ink);
  color: var(--ink-inverse);
  font-size: 10px;
  font-weight: 750;
  letter-spacing: 0.08em;
  line-height: 1;
}

.cityMeta {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  font-size: 12px;
  color: var(--ink-3);
  white-space: nowrap;
}

.offset {
  padding: 2px 6px;
  border-radius: 5px;
  background: var(--surface-sunken);
  border: 1px solid var(--border);
  color: var(--ink-2);
  font-family: var(--font-mono);
  font-size: 11px;
  line-height: 1.3;
  white-space: nowrap;
}

.cityClock {
  overflow: hidden;
  text-overflow: ellipsis;
  font-variant-numeric: tabular-nums;
}

.actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
}

.removeButton {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  padding: 0;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--ink-3);
  transition: background-color 140ms var(--ease), color 140ms var(--ease);
}

.removeButton:hover {
  background: var(--warn-soft);
  color: var(--warn-ink);
}

.cell[data-layout="desktop"] {
  flex-direction: column;
  gap: 4px;
  height: 54px;
}

.cellHour {
  font-size: 15px;
  font-weight: inherit;
  letter-spacing: -0.02em;
}

.cell[data-status="awake"] .cellHour {
  font-weight: 550;
}

.cellSub {
  font-size: 10px;
  font-weight: 600;
  opacity: 0.75;
  letter-spacing: 0.01em;
}

.cellSub[data-day] {
  opacity: 1;
  font-weight: 750;
  text-transform: uppercase;
  font-size: 9px;
  letter-spacing: 0.04em;
}

.cell[data-layout="desktop"][data-newday]::before {
  left: -2.5px;
  top: -3px;
  bottom: -3px;
  width: 2px;
}

.cell[data-layout="desktop"][data-now]::after {
  top: 4px;
  left: calc(50% - 2.5px);
}

/* ---------- Mobile: cities as columns ---------- */

.mobileScroll {
  overflow: auto;
  max-height: calc(100dvh - 96px);
  overscroll-behavior: contain;
  margin: 0 -4px;
  padding: 0 4px 4px;
}

.mobile {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: calc(var(--columns) * 86px);
}

.mobileRow {
  display: grid;
  grid-template-columns: repeat(var(--columns), minmax(82px, 1fr));
  gap: 3px;
}

.mobileRow[data-header] {
  position: sticky;
  top: 0;
  z-index: 5;
  padding-bottom: 6px;
  background: var(--surface);
}

.mobileHead {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  min-width: 0;
  padding: 10px 6px 8px;
  border-radius: var(--radius-md);
  background: var(--surface-sunken);
  border: 1px solid var(--border);
  text-align: center;
}

.mobileHead[data-reference] {
  border-color: var(--ink);
}

.mobileHead .cityNameRow {
  flex-direction: column;
  gap: 4px;
  max-width: 100%;
}

.mobileHead .cityName,
.mobileHead .cityNameButton {
  max-width: 100%;
  font-size: 14px;
  line-height: 1.2;
  text-align: center;
  white-space: normal;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.mobileHead .cityNameButton {
  text-decoration-color: var(--border-strong);
}

.mobileHead .removeButton {
  width: 26px;
  height: 22px;
  margin-top: -2px;
}

.cell[data-layout="mobile"] {
  gap: 5px;
  height: 38px;
  font-size: 14px;
}

.cellTime {
  letter-spacing: -0.01em;
}

.cellMeridiem {
  margin-left: 1px;
  font-size: 11px;
  font-weight: 600;
  opacity: 0.75;
}

.cellDay {
  padding: 2px 4px;
  border-radius: 4px;
  background: color-mix(in srgb, currentColor 14%, transparent);
  font-size: 9px;
  font-weight: 750;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.cell[data-layout="mobile"][data-newday]::before {
  top: -2.5px;
  left: -3px;
  right: -3px;
  height: 2px;
}

.cell[data-layout="mobile"][data-now]::after {
  left: 6px;
  top: calc(50% - 2.5px);
}

