.shell {
  display: flex;
  flex-direction: column;
  gap: 16px;
  max-width: 1320px;
  margin: 0 auto;
  padding: 40px 32px 48px;
}

.header {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 8px;
}

.logo {
  display: grid;
  place-items: center;
  flex: none;
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: var(--cell-overlap);
  color: var(--cell-overlap-ink);
  box-shadow: 0 6px 18px -6px var(--cell-overlap-glow);
}

.title {
  margin: 0;
  font-size: 26px;
  font-weight: 750;
  letter-spacing: -0.025em;
  line-height: 1.15;
}

.tagline {
  margin: 2px 0 0;
  color: var(--ink-2);
  font-size: 14px;
}

.controls {
  display: grid;
  grid-template-columns: minmax(280px, 1fr) minmax(0, 1.4fr);
  gap: 16px;
}

.board {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 20px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  min-width: 0;
}

.boardHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.boardTitle {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  font-size: 17px;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.count {
  display: inline-grid;
  place-items: center;
  min-width: 22px;
  height: 22px;
  padding: 0 6px;
  border-radius: 999px;
  background: var(--surface-sunken);
  border: 1px solid var(--border);
  font-size: 12px;
  font-weight: 650;
  color: var(--ink-2);
  font-variant-numeric: tabular-nums;
}

.boardHint {
  margin: 2px 0 0;
  font-size: 13px;
  color: var(--ink-3);
}

.boardFooter {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px 20px;
  padding-top: 14px;
  border-top: 1px solid var(--border);
}

.hint {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  font-size: 13px;
  font-weight: 600;
  color: var(--accent-green-ink);
}

.hint::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 2px;
  background: var(--cell-overlap);
}

.empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 48px 16px;
  border: 1px dashed var(--border-strong);
  border-radius: var(--radius-md);
  text-align: center;
  color: var(--ink-2);
  font-size: 14px;
}

.empty p {
  margin: 0;
}

.emptyTitle {
  font-size: 16px;
  font-weight: 650;
  color: var(--ink);
}

.linkButton {
  margin-top: 8px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--ink-2);
  font-size: 13px;
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 3px;
  text-decoration-color: var(--border-strong);
}

.linkButton:hover {
  color: var(--ink);
}

.pageFooter {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px 16px;
  padding: 4px 4px 0;
  font-size: 12px;
  color: var(--ink-3);
}

.pageFooter .linkButton {
  margin-top: 0;
  font-size: 12px;
}

@media (max-width: 1023px) {
  .controls {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 767px) {
  .shell {
    gap: 12px;
    padding: 20px 14px 32px;
  }

  .header {
    margin-bottom: 4px;
  }

  .title {
    font-size: 22px;
  }

